    "lt.v.sizeAndSpecial": { en: "Both a tumour size and a special T descriptor are entered. The special descriptor is used; check which one applies.", fi: "Sekä kasvaimen koko että T-erityisluokka on annettu. Käytössä on erityisluokka; tarkista, kumpi on oikea.", sv: "Både tumörstorlek och särskild T-kategori är angivna. Den särskilda kategorin används; kontrollera vilken som gäller.", no: "Både tumorstørrelse og spesiell T-kategori er oppgitt. Den spesielle kategorien brukes; kontroller hvilken som gjelder." },
    "lt.v.mEscalated": { en: "M category was raised to M1a because a contralateral lung nodule is recorded. Check the M category.", fi: "M-luokka nostettiin M1a:ksi, koska vastakkaisen keuhkon kyhmy on kirjattu. Tarkista M-luokka.", sv: "M-kategorin höjdes till M1a eftersom en kontralateral lungnodul är registrerad. Kontrollera M-kategorin.", no: "M-kategorien ble hevet til M1a fordi en kontralateral lungenodul er registrert. Kontroller M-kategorien." },
    "lt.v.curativeM1c": { en: "Curative intent is recorded together with M1c disease. Check intent and M category.", fi: "Kuratiivinen tavoite on kirjattu yhdessä M1c-taudin kanssa. Tarkista hoidon tavoite ja M-luokka.", sv: "Kurativ intention är registrerad tillsammans med M1c-sjukdom. Kontrollera intention och M-kategori.", no: "Kurativ intensjon er registrert sammen med M1c-sykdom. Kontroller intensjon og M-kategori." },
    "lt.v.surgeryN3": { en: "Surgery is selected together with N3. Check N category and treatment.", fi: "Leikkaus on valittu, vaikka luokka on N3. Tarkista N-luokka ja hoito.", sv: "Kirurgi är vald tillsammans med N3. Kontrollera N-kategori och behandling.", no: "Kirurgi er valgt sammen med N3. Kontroller N-kategori og behandling." },
    "lt.v.surgeryN2b": { en: "Surgery is selected together with multi-station N2 (N2b). Check the operability assessment.", fi: "Leikkaus on valittu, vaikka N2-tauti on usean imusolmukeaseman (N2b). Tarkista leikkauskelpoisuuden arvio.", sv: "Kirurgi är vald tillsammans med N2 i flera lymfkörtelstationer (N2b). Kontrollera operabilitetsbedömningen.", no: "Kirurgi er valgt sammen med N2 i flere lymfeknutestasjoner (N2b). Kontroller operabilitetsvurderingen." },
    "lt.v.surgeryBulkyN2": { en: "Surgery is selected together with bulky N2. Check the operability assessment.", fi: "Leikkaus on valittu, vaikka N2 on kookas. Tarkista leikkauskelpoisuuden arvio.", sv: "Kirurgi är vald tillsammans med bulky N2. Kontrollera operabilitetsbedömningen.", no: "Kirurgi er valgt sammen med bulky N2. Kontroller operabilitetsvurderingen." },
    "lt.v.bulkyMissing": { en: "N2 with surgery selected: record whether N2 is bulky.", fi: "N2 ja leikkaus valittu: kirjaa, onko N2 kookas.", sv: "N2 och kirurgi vald: ange om N2 är bulky.", no: "N2 og kirurgi valgt: oppgi om N2 er bulky." },
    "lt.v.radicalStagingIncomplete": { en: "Surgery or radical radiotherapy is selected while N or M is not assessed. Staging is incomplete.", fi: "Leikkaus tai radikaali sädehoito on valittu, vaikka N- tai M-luokkaa ei ole arvioitu. Levinneisyysselvitys on kesken.", sv: "Kirurgi eller radikal strålbehandling är vald trots att N eller M inte är bedömd. Stadieindelningen är ofullständig.", no: "Kirurgi eller radikal strålebehandling er valgt selv om N eller M ikke er vurdert. Stadieinndelingen er ufullstendig." },
    "lt.v.noneWithDriver": { en: "\"None detected\" is ticked together with a driver alteration. Untick one of them.", fi: "”Ei todettu” on valittu yhdessä ajurimutaation kanssa. Poista toinen valinta.", sv: "”Ingen påvisad” är markerad tillsammans med en drivarmutation. Avmarkera en av dem.", no: "«Ingen påvist» er krysset av sammen med en drivermutasjon. Fjern ett av kryssene." },
    "lt.v.twoEgfr": { en: "Two EGFR alterations are ticked. Only the first is exported to the EGFR status field; check.", fi: "Kaksi EGFR-mutaatiota on valittu. Vain ensimmäinen viedään EGFR-tilakenttään; tarkista.", sv: "Två EGFR-mutationer är markerade. Endast den första exporteras till fältet för EGFR-status; kontrollera.", no: "To EGFR-mutasjoner er krysset av. Bare den første eksporteres til feltet for EGFR-status; kontroller." },
    "lt.v.decisionNoTreatment": { en: "Decision status is \"Decision made\" but no treatment or supportive care is selected.", fi: "Päätöksen tila on ”Päätös tehty”, mutta hoitoa tai tukitoimea ei ole valittu.", sv: "Beslutsstatus är ”Beslut fattat” men ingen behandling eller understödjande åtgärd är vald.", no: "Beslutningsstatus er «Beslutning tatt», men ingen behandling eller støttetiltak er valgt." },
    "lt.v.conditionalNoTests": { en: "Decision is conditional on further tests, but no further investigation is selected.", fi: "Päätös riippuu lisätutkimuksista, mutta lisätutkimusta ei ole valittu.", sv: "Beslutet är villkorat av kompletterande utredning, men ingen utredning är vald.", no: "Beslutningen er betinget av supplerende utredning, men ingen utredning er valgt." },
    "lt.v.otherNeedsNote": { en: "Rationale is \"Other\": write the reason in one line.", fi: "Peruste on ”Muu”: kirjoita peruste yhdellä rivillä.", sv: "Motiveringen är ”Annat”: skriv skälet på en rad.", no: "Begrunnelsen er «Annet»: skriv grunnen på én linje." },
    "lt.v.dueBeforeMeeting": { en: "Next step due date is before the meeting date.", fi: "Seuraavan vaiheen määräpäivä on ennen kokouspäivää.", sv: "Datum för nästa steg ligger före mötesdatum.", no: "Dato for neste steg er før møtedatoen." },
    "lt.v.manualReview": { en: "Stage group cannot be assigned automatically from these T and N categories. Assess manually.", fi: "Levinneisyyttä ei voida määrittää automaattisesti näistä T- ja N-luokista. Arvioi käsin.", sv: "Stadium kan inte tilldelas automatiskt utifrån dessa T- och N-kategorier. Bedöm manuellt.", no: "Stadium kan ikke tildeles automatisk ut fra disse T- og N-kategoriene. Vurder manuelt." },
